CREATE TABLE order_status_domain (
    status_code text PRIMARY KEY,
    status_label text NOT NULL
);

INSERT INTO order_status_domain (status_code, status_label) VALUES
    ('placed', 'Placed'),
    ('paid', 'Paid'),
    ('fulfilled', 'Fulfilled'),
    ('cancelled', 'Cancelled');

CREATE TABLE customer_order (
    order_id integer PRIMARY KEY,
    order_status_code text NULL REFERENCES order_status_domain (status_code),
    status_knowledge text NOT NULL CHECK (
        status_knowledge IN ('known', 'unknown_from_source')
    ),
    CHECK (
        (status_knowledge = 'known' AND order_status_code IS NOT NULL)
        OR
        (status_knowledge = 'unknown_from_source' AND order_status_code IS NULL)
    )
);

CREATE TABLE order_status_exception (
    order_id integer PRIMARY KEY,
    raw_order_status text NULL,
    exception_reason text NOT NULL CHECK (
        exception_reason IN ('invalid_raw_value', 'wrong_attribute_question')
    )
);
